U=MANInstaller; export XDG_RUNTIME_DIR=/run/user/1001 DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1001/bus WAYLAND_DISPLAY=wayland-0
T=$(date +%s)
for a in org.gnome.Papers org.gnome.Decibels org.gnome.Snapshot org.gnome.Maps org.gnome.Settings org.gnome.Showtime org.gnome.Characters org.gnome.Weather org.gnome.Logs org.gnome.SimpleScan org.gnome.font-viewer org.gnome.Yelp org.gnome.Music org.gnome.baobab org.gnome.Calculator org.gnome.Loupe org.gnome.TextEditor org.gnome.Calendar org.gnome.clocks org.gnome.Contacts org.gnome.Connections org.gnome.SystemMonitor org.gnome.DiskUtility org.gnome.Epiphany org.gnome.Console org.gnome.Nautilus; do runuser -u $U -- env XDG_RUNTIME_DIR=$XDG_RUNTIME_DIR DBUS_SESSION_BUS_ADDRESS=$DBUS_SESSION_BUS_ADDRESS WAYLAND_DISPLAY=$WAYLAND_DISPLAY gtk-launch $a.desktop >/dev/null 2>&1 & sleep 2; done
sleep 25
for a in org.gnome.Papers org.gnome.Decibels org.gnome.Snapshot org.gnome.Maps org.gnome.Settings org.gnome.Showtime org.gnome.Characters org.gnome.Weather org.gnome.Logs org.gnome.SimpleScan org.gnome.font-viewer org.gnome.Yelp org.gnome.Music org.gnome.baobab org.gnome.Calculator org.gnome.Loupe org.gnome.TextEditor org.gnome.Calendar org.gnome.clocks org.gnome.Contacts org.gnome.Connections org.gnome.SystemMonitor org.gnome.DiskUtility org.gnome.Epiphany org.gnome.Console org.gnome.Nautilus; do n=$(ps -u $U -o args= | grep -iF -c "$(grep -m1 '^Exec=' /usr/share/applications/$a.desktop | sed 's/^Exec=//;s/ .*//;s|.*/||')"); printf '%-26s %s\n' $a $( [ $n -gt 0 ] && echo RUNNING || echo NOT-RUNNING); done
echo "== crashes/errors:"; journalctl --since @$T -o cat _UID=1001 | grep -iE 'core dumped|segfault|Traceback|ImportError|ModuleNotFound|cannot open shared|undefined symbol|error while loading|Failed to load|exited, code=exited, status=[1-9]' | sort | uniq -c | sort -rn | head -20
